import React from 'react';
import * as illustrations from '..';
import type { IllustrationType } from '../../types';

interface L1IconTypeDemo extends IllustrationType {
  iconName: keyof typeof illustrations;
}

const Demo = ({ iconName, size = 'md' }: L1IconTypeDemo) => {
  const Illustration = illustrations[iconName];
  return <Illustration size={size} />;
};

export default Demo;
